class Solution {
    public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        java.util.Set<Long> blockSet = new java.util.HashSet<>();
        for (int[] b : blocked) blockSet.add((long) b[0] * 1000000 + b[1]);
        return bfs(blockSet, source, target) && bfs(blockSet, target, source);
    }
    private boolean bfs(java.util.Set<Long> blockSet, int[] start, int[] end) {
        java.util.Set<Long> visited = new java.util.HashSet<>();
        java.util.Queue<int[]> queue = new java.util.LinkedList<>();
        queue.offer(start);
        visited.add((long) start[0] * 1000000 + start[1]);
        int limit = 20000;
        int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
        while (!queue.isEmpty() && visited.size() < limit) {
            int[] cur = queue.poll();
            if (cur[0] == end[0] && cur[1] == end[1]) return true;
            for (int[] d : dirs) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                long key = (long) nr * 1000000 + nc;
                if (nr >= 0 && nr < 1000000 && nc >= 0 && nc < 1000000 && !blockSet.contains(key) && visited.add(key))
                    queue.offer(new int[]{nr, nc});
            }
        }
        return visited.size() >= limit;
    }
}

import java.util.*;

class Solution {
    public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<Long> blockSet = new HashSet<>();
        for (int[] b : blocked) blockSet.add((long) b[0] * 1000000 + b[1]);
        int limit = blocked.length * blocked.length / 2 + blocked.length;
        return canEscape(blockSet, source, target, limit) && canEscape(blockSet, target, source, limit);
    }
    private boolean canEscape(Set<Long> blockSet, int[] start, int[] end, int limit) {
        Set<Long> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(start);
        visited.add((long) start[0] * 1000000 + start[1]);
        int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
        while (!queue.isEmpty()) {
            if (visited.size() > limit) return true;
            int[] cur = queue.poll();
            if (cur[0] == end[0] && cur[1] == end[1]) return true;
            for (int[] d : dirs) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                long key = (long) nr * 1000000 + nc;
                if (nr >= 0 && nr < 1000000 && nc >= 0 && nc < 1000000
                    && !blockSet.contains(key) && visited.add(key)) {
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return false;
    }
}
